relativeRuntimeProof.source:
with tempfile.TemporaryDirectory(prefix='c1-ses-runtime-') as temporary:
    root=Path(temporary)
    for name in ['home','tmp','work']:
        (root/name).mkdir()
    environment={'PATH':'/usr/bin:/bin','HOME':str(root/'home'),'TMPDIR':str(root/'tmp'),'LANG':'C.UTF-8'}
    commands=[
        ('Supported runner from unrelated cwd with existing relative JS selectors',['/usr/bin/node',str(repo/'scripts/run-tests.js'),*ses_paths]),
        ('Direct Node generated JS programs from unrelated cwd',['/usr/bin/node','--test',*[str(repo/p) for p in ses_paths]])
    ]
    runtime_results=[]
    for label,command in commands:
        result=ses_command_proof(label,command,environment,120,root/'work')
        if result.returncode!=0:
            raise RuntimeError('Actual runtime proof failed; preserve result and do not retry blindly')
        counts={title:len(re.findall(r'^✔ '+re.escape(title)+r' \(',result.stdout,re.MULTILINE)) for titles in ses_titles.values() for title in titles}
        assert len(counts)==16 and all(count==1 for count in counts.values())
        assert not list((root/'tmp').iterdir()) and not list((root/'home').iterdir())
        runtime_results.append({'label':label,'eachExistingCaseRunsExactlyOnce':counts,'homeAndTemporaryRootEmptyAfterRun':True})
    ses_evidence['relativeRuntimeProof']['results']=runtime_results
